INSERT INTO practice_cases (system_id,title,modality,difficulty,clinical_info,question_text,correct_answer,explanation,key_findings,learning_points,differential_diagnosis,status) VALUES (@sys,'Mock MRI: right frontal lesion','MRI','medium','Headaches for 3 weeks. (Synthetic mock image for app testing, not a real patient.)','What is the most likely diagnosis? Scroll through all 20 slices.','Brain tumour | Brain tumor | Glioma | Intracranial mass','Mock case for testing the scrolling viewer. Rounded bright lesion in the right frontal lobe with a surrounding halo of oedema, seen on about slices 7 to 14 of 20.','Rounded bright lesion in the right frontal lobe with a surrounding halo of oedema, seen on about slices 7 to 14 of 20.','Look for a focal bright rounded area with a rim of swelling; it appears and disappears as you scroll.','Hydrocephalus; Ischaemic stroke','published');
