INSERT INTO practice_cases (system_id,title,modality,difficulty,clinical_info,question_text,correct_answer,explanation,key_findings,learning_points,differential_diagnosis,status) VALUES (@sys,'Mock MRI: left hemisphere wedge','MRI','medium','Sudden weakness on the right side of the body. (Synthetic mock image for app testing, not a real patient.)','What is the most likely diagnosis? Scroll through all 20 slices.','Ischaemic stroke | Ischemic stroke | Acute infarct | Cerebral infarction','Mock case for testing the scrolling viewer. Wedge-shaped bright area in the left hemisphere, seen on about slices 8 to 14 of 20, with no mass effect on the ventricles.','Wedge-shaped bright area in the left hemisphere, seen on about slices 8 to 14 of 20, with no mass effect on the ventricles.','A wedge-shaped bright region following a vascular territory points to an infarct rather than a mass.','Brain tumour; Hydrocephalus','published');
