INSERT INTO practice_cases (system_id,title,modality,difficulty,clinical_info,question_text,correct_answer,explanation,key_findings,learning_points,differential_diagnosis,status) VALUES (@sys,'Mock MRI: enlarged ventricles','MRI','easy','Worsening headache and unsteady walking. (Synthetic mock image for app testing, not a real patient.)','What is the most likely diagnosis? Scroll through all 20 slices.','Hydrocephalus','Mock case for testing the scrolling viewer. Both lateral ventricles are markedly enlarged and bright, seen on about slices 6 to 15 of 20, with no separate focal lesion.','Both lateral ventricles are markedly enlarged and bright, seen on about slices 6 to 15 of 20, with no separate focal lesion.','Compare ventricle size with the other cases: much larger and symmetrical on both sides.','Brain tumour; Ischaemic stroke','published');
